//! The generated coefficient tables, one module per tier.
//!
//! Generated by `cargo xtask ephemgen`. Do not edit.
//!
//! A tier is a cargo feature, and exactly one is in the binary: a
//! consumer who takes `compact` pays for `compact`, which is what
//! makes the tier mean anything on a platform that counts
//! kilobytes.
//!
//! | tier | planets | Moon | data of budget | source |
//! |---|---|---|---:|---:|
//! | `compact` | 3e-6 au, 21.2729″, 2503 terms | 1, 18.0895″, 160 terms | 83 of 128 KB | 129 KB |
//! | `standard` | 3e-8 au, 0.6190″, 15860 terms | 0.01, 0.7131″, 1139 terms | 531 of 640 KB | 763 KB |
//! | `full` | whole theory, 0.0000″, 39198 terms | whole theory, 0.0000″, 37872 terms | 2408 of 4096 KB | 4231 KB |

#[cfg(all(feature = "compact", not(feature = "standard"), not(feature = "full")))]
#[rustfmt::skip]
mod compact;
#[cfg(all(feature = "compact", not(feature = "standard"), not(feature = "full")))]
pub use compact::*;

#[cfg(all(feature = "standard", not(feature = "full")))]
#[rustfmt::skip]
mod standard;
#[cfg(all(feature = "standard", not(feature = "full")))]
pub use standard::*;

#[cfg(feature = "full")]
#[rustfmt::skip]
mod full;
#[cfg(feature = "full")]
pub use full::*;

/// The tier these tables came from, for provenance: a chart says
/// which tier computed it, and a cached one says which tier it was
/// cached from (ADR-0020).
pub const TIER: &str = {
    #[cfg(feature = "full")]
    { "full" }
    #[cfg(all(feature = "standard", not(feature = "full")))]
    { "standard" }
    #[cfg(all(feature = "compact", not(feature = "standard"), not(feature = "full")))]
    { "compact" }
};
